{
  "root_causes": [
    {
      "service": "ts-user-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-user-service' AND span_name IN ('UserController.getAllUser','UserRepository.findAll') GROUP BY 1", "claim": "getAllUser controller takes ~1607 ms while its DB call findAll takes ~6 ms, so the time is inside the method."},
        {"kind": "trace", "sql": "SELECT 'norm' src, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM normal_traces WHERE service_name='ts-user-service' AND span_name IN ('UserController.getAllUser','UserRepository.findAll') GROUP BY 1,2", "claim": "Before the incident getAllUser averaged about 3.3 ms and findAll about 2.6 ms."},
        {"kind": "metric", "sql": "SELECT 'abn' src, round(avg(value),3) avg_cpu FROM abnormal_metrics WHERE metric='container.cpu.usage' AND service_name='ts-user-service' UNION ALL SELECT 'norm', round(avg(value),3) FROM normal_metrics WHERE metric='container.cpu.usage' AND service_name='ts-user-service'", "claim": "ts-user-service container CPU usage is unchanged (about 0.04 abnormal vs 0.05 normal), so it is not CPU saturation."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-user-service' AND span_name='GET /api/v1/userservice/users' GROUP BY 1,2", "claim": "The user-service GET /users server span averages about 1608 ms, the same slow path."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-user-service", "to": "ts-admin-user-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE (service_name='ts-admin-user-service' AND span_name='GET /api/v1/adminuserservice/users') OR (service_name='ts-user-service' AND span_name='GET /api/v1/userservice/users') GROUP BY 1,2", "claim": "admin-user GET server span rises to about 1614 ms, matching the ~1608 ms user-service GET it waits on (was ~10 ms normal)."}]},
    {"from": "ts-admin-user-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT 'abn' src, service_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/adminuserservice/users' GROUP BY 1,2 UNION ALL SELECT 'norm', service_name, count(*), round(avg(duration)/1e6,1) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/adminuserservice/users' GROUP BY 1,2", "claim": "The user-facing dashboard request GET /adminuserservice/users rises from about 11.5 ms to about 1616 ms."}]}
  ]
}
